import { useCallback, useEffect, useRef, useState } from "react";
import type { CSSProperties, HTMLAttributes, ReactNode, Ref } from "react";
import "./ScrollArea.css";

type ScrollAreaOrientation = "vertical" | "horizontal" | "both";

export interface ScrollAreaProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * Scroll direction.
   *
   * @default "vertical"
   */
  orientation?: ScrollAreaOrientation;
  /** Scrollable content. */
  children?: ReactNode;
  /** Additional class. sd-scroll-area is always retained. */
  className?: string;
  /** Inline style passthrough. */
  style?: CSSProperties;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ScrollArea({
  orientation = "vertical",
  className,
  /* A scrollable region must be keyboard-focusable so it can be scrolled without a pointer (axe
     scrollable-region-focusable / WCAG 2.1.1) — but ONLY while it actually scrolls. An unconditional
     tab stop on a region whose content fits is a focus ring on a control that cannot act, and it is
     the defect this default used to ship: every ScrollArea took a tab stop whether or not there was
     anything to reach. `Carousel` already solved this for its viewport by measuring, and states the
     rule outright — "never a dead focus ring, never an unreachable scroll region". This is that same
     mechanism, moved into the primitive so callers inherit it instead of re-deriving it.
     Pass `tabIndex` explicitly to override in either direction. */
  tabIndex,
  ref,
  ...props
}: ScrollAreaProps) {
  /* The measurement needs the node, and so may the CALLER — `ScrollAreaProps` forwards `ref`
     (component-contract.md §5). Spreading props while also setting an internal `ref` would have let
     this component silently swallow the caller's, so both are attached through one callback.
     Two things this has to get right, both easy to miss:
     · React 19 lets a callback ref RETURN a cleanup, and then does not call `ref(null)` on detach.
       So a composed callback must return one too, and inside it run the caller's cleanup if it gave
       us one — otherwise a caller that installs a listener in its ref leaks it forever. When it gave
       us none, we owe it the legacy `ref(null)` instead.
     · It must be stable. React re-invokes a ref callback whose identity changed, so an inline
       `attach` would detach and re-attach the node on EVERY render. (A caller passing an inline
       arrow as `ref` still pays that cost — its own identity churns — but that is the caller's to
       fix, and it stays correct either way.) */
  const inner = useRef<HTMLDivElement | null>(null);
  const attach = useCallback(
    (node: HTMLDivElement | null) => {
      inner.current = node;
      if (typeof ref === "function") {
        const cleanup = ref(node);
        return () => {
          inner.current = null;
          if (typeof cleanup === "function") cleanup();
          else ref(null);
        };
      }
      if (ref) ref.current = node;
      return () => {
        inner.current = null;
        if (ref) ref.current = null;
      };
    },
    [ref],
  );
  const [isScrollable, setIsScrollable] = useState(false);
  // Which ends of the scrolling axis hold more content, so the CSS can fade that edge: a region cut
  // at its edge otherwise reads as complete. One axis only; `both` shows no cue.
  const [overflow, setOverflow] = useState({ start: false, end: false });

  useEffect(() => {
    const el = inner.current;
    if (!el) return;
    /* Only the axis this orientation actually SCROLLS counts. The other one is `overflow: hidden`
       (ScrollArea.css), so content overflowing it is clipped, unreachable by keyboard either way —
       a tab stop earned from that axis would be exactly the dead focus ring measuring is here to
       prevent. The `+ 1` is deliberate and matches `Carousel`: these are rounded integers, so a box
       with a fractional width reports `scrollWidth === clientWidth + 1` while scrolling nowhere.
       It costs a genuine one-pixel range, which hides no content anyone can read; the alternative
       spends a spurious tab stop on every subpixel layout. */
    const scrollsX = orientation !== "vertical";
    const scrollsY = orientation !== "horizontal";
    const measure = () => {
      setIsScrollable(
        (scrollsX && el.scrollWidth > el.clientWidth + 1) ||
          (scrollsY && el.scrollHeight > el.clientHeight + 1),
      );
      if (orientation === "both") {
        setOverflow((cur) => (cur.start || cur.end ? { start: false, end: false } : cur));
        return;
      }
      const [pos, size, view] = scrollsX
        ? [Math.abs(el.scrollLeft), el.scrollWidth, el.clientWidth] // abs: RTL scrolls negative
        : [el.scrollTop, el.scrollHeight, el.clientHeight];
      const start = pos > 1;
      const end = pos + view < size - 1;
      setOverflow((cur) => (cur.start === start && cur.end === end ? cur : { start, end }));
    };
    measure();
    el.addEventListener("scroll", measure, { passive: true });
    // The box AND its content: a resize changes the former, new or grown content the latter. EVERY
    // child, not just the first — `children` is arbitrary here, so the one that grows is not
    // necessarily the one in front (`Carousel` can observe just its track because it renders it).
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    for (const child of Array.from(el.children)) observer.observe(child);
    return () => {
      observer.disconnect();
      el.removeEventListener("scroll", measure);
    };
    // No dependency array on purpose. ScrollArea takes arbitrary `children`, so unlike `Carousel`
    // (which keys its effect on its own item `count`) there is no signal that says "the content
    // changed". Re-subscribing per render is the correct-by-default choice: the alternative, `[]`,
    // holds a stale child list the moment the content is replaced rather than resized, and a scroll
    // region that stops being focusable while it is still scrollable is a WCAG 2.1.1 failure. The
    // cost is one observer teardown/setup per render, which is cheaper than that failure. What this
    // still cannot see is a DESCENDANT that grows from its own state without changing any observed
    // child's box — that needs one shared, subtree-aware hook (QUEUE.md § Next).
  });

  return (
    <div
      {...props}
      ref={attach}
      tabIndex={tabIndex ?? (isScrollable ? 0 : undefined)}
      data-orientation={orientation}
      data-overflow-start={overflow.start || undefined}
      data-overflow-end={overflow.end || undefined}
      className={className ? `sd-scroll-area ${className}` : "sd-scroll-area"}
    />
  );
}

/* SCROLLBAR CHROME IS BORROWED, NOT OWNED (AGENTS.md § Core principle: Own vs Borrow). We set the standard pair and
   the UA draws the bar; we own its colour and nothing else.

   No `::-webkit-scrollbar*` block. A non-`auto` `scrollbar-width` suppresses the legacy
   pseudo-element styling, so wherever the standard property lands the webkit rules stop applying;
   only Safari ≤18.1, which predates `scrollbar-width`, would still honour them, and a single code
   path is worth that narrowing case.

   So no size, thumb radius or thumb hover is owned here: the size and radius have no standard
   equivalent (`thin` is a keyword), and a hover on the THUMB is not expressible either.
   `.sd-scroll-area:hover` fires whenever the pointer is anywhere in the scrollport, a different
   affordance, and states a hover in CSS where §6 wants a React Aria `data-*`. What the platform
   lets us own here is one colour. */
.sd-scroll-area {
  --sd-scroll-area-fade-start-current: 0px;
  --sd-scroll-area-fade-end-current: 0px;
  --sd-scroll-area-fade-direction-current: to bottom;
  /* §6-3: the DS ring is drawn below, so the UA outline is reset on the BASE rule —
     inside the focus rule it lands too late and the OS accent paints alongside ours. */
  outline: none;
  scrollbar-width: thin;
  scrollbar-color: var(--sd-scroll-area-thumb) transparent;
  /* The larger of the two things that paint past a child's box at the content edge: a focus ring
     and a row's bled state fill (component-contract.md §6 rule 8). */
  --sd-scroll-area-gutter-current: max(var(--sd-state-focus-ring-width), var(--sd-scroll-area-gutter));
}

/* A compensated scrollport, the pattern `Tabs`, `Dialog` and `Drawer` `__scroll` use: the padding
   moves the clip edge out past a ring or a bleed at the content edge, and the equal negative margin
   hands the space back, so the content sits exactly where it did. Both axes, because either one
   clips (`overflow-x: auto` forces `overflow-y` off `visible`, and the reverse), so a Switch's ring at
   the start edge is not cut.
   `:where()` keeps this at zero specificity, so any unit that reuses the scrollport as its own root
   or sets its own spacing on it (Tabs' strip, a Block's `__scroll`) wins outright, whatever order
   the stylesheets load in. A root that PAINTS a surface must reset both (MessagePreview does):
   the negative margin would otherwise grow its painted box. With an explicit size under
   `box-sizing: border-box`, the content box is the size minus twice the gutter. */
:where(.sd-scroll-area) {
  padding: var(--sd-scroll-area-gutter-current);
  margin: calc(-1 * var(--sd-scroll-area-gutter-current));
}

/* The scrollport is a tab stop (see the tsx: axe `scrollable-region-focusable` / WCAG 2.1.1), so it
   draws the library's ring like every other focusable part — `docs/rules/accessibility.md` § 2.4.7 names
   the token ring as the owned mechanism, and until now this was the one focusable surface still
   showing whatever the UA drew. Same rule as `Carousel`'s viewport, the library's other scrollport. */
.sd-scroll-area:focus-visible {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-scroll-area[data-orientation="vertical"] {
  overflow-x: hidden;
  overflow-y: auto;
}

.sd-scroll-area[data-orientation="horizontal"] {
  overflow-x: auto;
  overflow-y: hidden;
}

.sd-scroll-area[data-orientation="both"] {
  overflow: auto;
}

.sd-scroll-area[data-orientation="horizontal"] {
  --sd-scroll-area-fade-direction-current: to right;
}
.sd-scroll-area[data-orientation="horizontal"]:dir(rtl) {
  --sd-scroll-area-fade-direction-current: to left;
}

/* More to scroll to past an edge: that edge fades, so a table cut at the viewport reads as cut
   rather than as complete. Only while there is overflow, because a mask clips at the border box and
   would also clip the focus ring; for the same reason it lifts while focus is anywhere inside the
   region, so a focused cell or tab near an edge is never faded under its own ring. */
.sd-scroll-area[data-overflow-start] {
  --sd-scroll-area-fade-start-current: var(--sd-scroll-area-fade-size);
}
.sd-scroll-area[data-overflow-end] {
  --sd-scroll-area-fade-end-current: var(--sd-scroll-area-fade-size);
}
.sd-scroll-area[data-overflow-start],
.sd-scroll-area[data-overflow-end] {
  mask-image: linear-gradient(
    var(--sd-scroll-area-fade-direction-current),
    transparent,
    #000 var(--sd-scroll-area-fade-start-current),
    #000 calc(100% - var(--sd-scroll-area-fade-end-current)),
    transparent
  );
}
.sd-scroll-area:focus-within {
  mask-image: none;
}
